<template><div v-if="open" class="demo-modal-backdrop" @click.self="cancel"><section ref="modal" class="demo-action-modal" role="dialog" aria-modal="true" :aria-labelledby="`${id}-title`" @keydown.esc="cancel"><header><h2 :id="`${id}-title`">{{ title }}</h2><button type="button" aria-label="Close dialog" @click="cancel">×</button></header><div class="demo-modal-body"><p>{{ description }}</p><p v-if="warning" class="demo-modal-warning">{{ warning }}</p><label>{{ fieldLabel }}<textarea ref="field" v-model="reason" rows="4" :aria-describedby="error ? `${id}-error` : undefined"></textarea></label><p v-if="error" :id="`${id}-error`" class="criterion-error" role="alert">{{ error }}</p></div><footer><button type="button" @click="cancel">Cancel</button><button type="button" :disabled="submitting" @click="confirm">{{ submitting ? 'Working…' : confirmLabel }}</button></footer></section></div></template>
<script>import { nextTick } from 'vue'; export default { name: 'DemoActionModal', props: { open: { type: Boolean, default: true }, id: { type: String, default: 'demo-action' }, title: String, description: String, warning: String, fieldLabel: { type: String, default: 'Internal reason' }, confirmLabel: { type: String, default: 'Confirm' } }, emits: ['cancel','confirm'], data: () => ({ reason: '', error: '', submitting: false }), async mounted() { if (this.open) { await nextTick(); this.$refs.field?.focus(); } }, watch: { async open(value) { if (value) { this.reason = ''; this.error = ''; this.submitting = false; await nextTick(); this.$refs.field?.focus(); } } }, methods: { cancel() { if (!this.submitting) this.$emit('cancel'); }, async confirm() { if (!this.reason.trim()) { this.error = `${this.fieldLabel} is required.`; this.$refs.field?.focus(); return; } this.submitting = true; try { await this.$emit('confirm', this.reason.trim()); } finally { this.submitting = false; } } } };</script>
